<?php
require_once __DIR__.'/includes/bootstrap.php';
$user=require_login();$error='';$teacher=is_teacher($user);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='create' && !$teacher){
  $name=trim($_POST['name']??'');$course=trim($_POST['course']??'');
  if($name==='')$error='Nama kelompok wajib diisi.';
  else{$g=['id'=>bin2hex(random_bytes(5)),'invite_code'=>strtoupper(bin2hex(random_bytes(3))),'name'=>$name,'course'=>$course?:'PBL','created_by'=>(int)$user['id'],'member_ids'=>[(int)$user['id']],'members'=>[['user_id'=>(int)$user['id'],'name'=>$user['name'],'role'=>'Ketua','joined_at'=>date('Y-m-d')]],'created_at'=>date('Y-m-d')];save_group($g);log_activity('Kelompok dibuat',$name,'success');flash('Kelompok berhasil dibuat. Bagikan kode undangan kepada anggota.');redirect('teams.php');}
 }
 if($action==='join' && !$teacher){
  $code=strtoupper(trim($_POST['code']??''));$groups=all_groups();$found=false;
  foreach($groups as &$g){if(strtoupper((string)($g['invite_code']??''))===$code || (string)($g['id']??'')===$code){$ids=array_map('intval',$g['member_ids']??[]);if(!in_array((int)$user['id'],$ids,true)){$g['member_ids'][]=(int)$user['id'];$g['members'][]=['user_id'=>(int)$user['id'],'name'=>$user['name'],'role'=>'Anggota','joined_at'=>date('Y-m-d')];$found=true;}break;}}unset($g);
  if($found){write_data('groups.json',$groups);log_activity('Anggota bergabung','Bergabung ke kelompok melalui undangan','success');flash('Berhasil bergabung ke kelompok.');redirect('teams.php');}else $error='Kode undangan tidak valid atau kamu sudah menjadi anggota.';
 }
 if($action==='invite' && !$teacher){$gid=(string)($_POST['group_id']??'');$group=group_by_id($gid);if(!$group || !can_manage_group($group,$user)){$error='Hanya ketua kelompok yang dapat mengelola undangan.';}else{if(empty($group['invite_code'])){$group['invite_code']=strtoupper(bin2hex(random_bytes(3)));save_group($group);}flash('Kode undangan: '.group_invite_code($group));redirect('teams.php');}}
}
$groups=visible_groups($user);layout_start('Tim & Kelompok','teams');
$headingAction=(!$teacher?'<a class="btn primary" href="#create-group">＋ Buat kelompok</a>':'<a class="btn secondary" href="classroom.php">Monitor kelas ↗</a>');
page_heading($teacher?'MONITORING AKADEMIK':'WORKSPACE / TIM',$teacher?'Seluruh Kelompok':'Tim & Kelompok',$teacher?'Pantau kelompok dan progres proyek yang berada dalam ruang lingkup pengajaranmu.':'Kelola ruang kerja, undang anggota, dan pantau proyek kolaborasi.',$headingAction);
if($error)echo '<div class="flash error">'.e($error).'</div>';
echo '<div class="stats-grid three-stats"><article class="stat-card"><div class="stat-label">'.($teacher?'TOTAL KELOMPOK':'KELOMPOK SAYA').'</div><div class="stat-number">'.count($groups).'</div><div class="stat-foot">'.($teacher?'Kelompok terdaftar':'Workspace yang diikuti').'</div></article><article class="stat-card"><div class="stat-label">TOTAL ANGGOTA</div><div class="stat-number">'.array_sum(array_map(fn($g)=>count($g['members']??[]),$groups)).'</div><div class="stat-foot">'.($teacher?'Dari kelompok yang dipantau':'Di seluruh kelompokmu').'</div></article><article class="stat-card"><div class="stat-label">AKSES</div><div class="stat-number"><small>'.($teacher?'DOSEN / AUDITOR':'MAHASISWA').'</small></div><div class="stat-foot">Data ditampilkan sesuai role</div></article></div>';
echo '<div class="team-layout"><section class="panel"><div class="panel-heading"><div><div class="panel-title">'.($teacher?'Kelompok dalam pemantauan':'Workspace kelompok').'</div><div class="panel-sub">'.($teacher?'Ringkasan seluruh kelompok pada ruang lingkup ini':'Kelompok yang kamu ikuti').'</div></div><span class="counter">'.count($groups).' total</span></div>';
if(!$groups)echo '<div class="empty-state"><span class="empty-illustration">♧</span><b>Belum ada kelompok</b><p>'.($teacher?'Kelompok yang dibuat mahasiswa akan muncul di sini.':'Buat kelompok baru atau gabung menggunakan kode undangan dari ketua kelompok.').'</p></div>';
foreach($groups as $g){$members=$g['members']??[];$code=group_invite_code($g);echo '<article class="group-card"><div class="group-card-head"><div class="group-symbol">✦</div><div class="group-main"><h3>'.e($g['name']).'</h3><p>'.e($g['course']??'PBL').' · Dibuat '.e(format_date($g['created_at']??'')).'</p></div>'.($teacher?'<span class="status-badge good">Mode monitor</span>':'<button class="icon-btn" type="button" data-copy="'.e($code).'" title="Salin kode undangan">⧉</button>').'</div><div class="group-meta"><span>♧ '.count($members).' anggota</span><span>⌁ '.($teacher?'Ketua: ':'Kode: ').'<b>'.e($teacher?($members[0]['name']??'Belum ada'):($code?:$g['id'])).'</b></span></div><div class="member-stack">';foreach(array_slice($members,0,6) as $m)echo '<span class="avatar" title="'.e($m['name']??'Anggota').'">'.e(mb_strtoupper(mb_substr($m['name']??'?',0,1))).'</span>';echo '</div><div class="group-card-foot"><span class="status-badge good">● Workspace aktif</span><a class="text-link" href="tasks.php?group='.e($g['id']).'">Lihat tugas →</a></div>';if(!$teacher && can_manage_group($g,$user))echo '<div class="invite-strip"><div><b>Undang anggota</b><small>Bagikan kode ini kepada mahasiswa yang ingin bergabung.</small></div><code>'.e($code).'</code><button class="btn secondary small" type="button" data-copy="'.e($code).'">Salin kode</button></div>';echo '</article>';}
echo '</section>';
if(!$teacher)echo '<aside class="panel side-form" id="create-group"><div class="panel-title">Buat kelompok</div><p class="panel-sub">Buat workspace baru untuk mata kuliah atau proyek.</p><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="create"><label>Nama kelompok</label><input name="name" required maxlength="100" placeholder="Contoh: Kelompok PBL 01"><label>Mata kuliah / proyek</label><input name="course" maxlength="100" placeholder="Contoh: Project Based Learning"><button class="btn primary full-width">＋ Buat workspace</button></form><div class="form-separator"></div><div class="panel-title">Gabung kelompok</div><p class="panel-sub">Masukkan kode undangan yang diberikan ketua kelompok.</p><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="join"><label>Kode undangan</label><input name="code" required maxlength="40" placeholder="Contoh: A4B8C1"><button class="btn secondary full-width">Gabung kelompok →</button></form></aside>';
else echo '<aside class="panel side-form"><div class="panel-title">Akses dosen</div><p class="panel-sub">Dosen dapat melihat ringkasan seluruh kelompok yang tersedia. Akses produksi sebaiknya dipetakan ke kelas/mata kuliah yang diampu.</p><a class="btn primary full-width" href="classroom.php">Buka monitor kelas →</a><div class="form-separator"></div><div class="panel-title">Batas akses</div><p class="panel-sub">Mahasiswa hanya melihat kelompok tempat akunnya terdaftar. Pengelolaan anggota dibatasi untuk ketua kelompok.</p></aside>';
echo '</div>';layout_end();
